package com.example.Hospital.Management.System.services; import com.example.Hospital.Management.System.entities.*; import com.example.Hospital.Management.System.dtos.*; import com.example.Hospital.Management.System.repositories.*; import com.example.Hospital.Management.System.exceptions.*; import org.springframework.stereotype.Service; import java.util.*; @Service public class MedicalRecordService{private final MedicalRecordRepository r;private final PatientRepository pr;public MedicalRecordService(MedicalRecordRepository r,PatientRepository pr){this.r=r;this.pr=pr;} private MedicalRecord find(Long id){return r.findById(id).filter(BaseClass::getIsActive).orElseThrow(()->new ResourceNotFoundException("Medical record not found"));} private MedicalRecordDTO dto(MedicalRecord e){return MedicalRecordDTO.builder().id(e.getId()).diagnosis(e.getDiagnosis()).notes(e.getNotes()).recordDate(e.getRecordDate()).patientId(e.getPatient().getId()).build();} private void apply(MedicalRecord e,MedicalRecordDTO d){Patient p=pr.findById(d.getPatientId()).filter(BaseClass::getIsActive).orElseThrow(()->new ResourceNotFoundException("Patient not found"));e.setDiagnosis(d.getDiagnosis());e.setNotes(d.getNotes());e.setRecordDate(d.getRecordDate());e.setPatient(p);} public MedicalRecordDTO create(MedicalRecordDTO d){MedicalRecord e=new MedicalRecord();apply(e,d);return dto(r.save(e));} public List<MedicalRecordDTO> all(){return r.findByIsActiveTrue().stream().map(this::dto).toList();} public MedicalRecordDTO get(Long id){return dto(find(id));} public MedicalRecordDTO update(Long id,MedicalRecordDTO d){MedicalRecord e=find(id);apply(e,d);return dto(r.save(e));} public void delete(Long id){MedicalRecord e=find(id);e.setIsActive(false);r.save(e);} public List<MedicalRecordDTO> patient(Long id){return r.findByPatientIdAndIsActiveTrue(id).stream().map(this::dto).toList();}}
